  if (totalLength > maximumLength) {
    throw new IDNAError("Domain too long");
  }
}

export function encode(domain) {
  const input = String(domain);
  const { labels, trailingDot } = splitDomain(input);
  const encodedLabels = labels.map((label) => encodeLabel(label));
  const asciiDomain = joinDomain(encodedLabels, trailingDot);
  checkDomainLength(asciiDomain, trailingDot);
  return toByteBuffer(asciiDomain);
}

export function decode(domain) {
  const input = typeof domain === "string" ? domain : bufferToString(domain);
  const { labels, trailingDot } = splitDomain(input);
  const decodedLabels = labels.map((label) => decodeLabel(label));
  return joinDomain(decodedLabels, trailingDot);
}

export function alabel(label) {
  return toByteBuffer(encodeLabel(String(label)));
}

export function ulabel(label) {
  const input = typeof label === "string" ? label : bufferToString(label);
  return decodeLabel(input);
}

export class CLIUsageError extends Error {
  constructor(message) {
    super(message);
    this.name = "CLIUsageError";
  }
}

const NEGATIVE_NUMBER_RE = /^-\d+(\.\d*)?$|^-\.\d+$/;
const HELP_OPTION = "--help";
const DOMAIN_OPTION = "--domain";

function acceptsOptionalValue(token) {
  return token === "-" || !token.startsWith("-") || NEGATIVE_NUMBER_RE.test(token);
}

function isLongOptionPrefix(token, option) {
  return token.startsWith("--") && option.startsWith(token);
}

function splitOptionToken(token) {
  const equalsIndex = token.indexOf("=");

  if (equalsIndex === -1) {
    return { optionToken: token, explicitValue: undefined };
  }

  return {
    optionToken: token.slice(0, equalsIndex),
    explicitValue: token.slice(equalsIndex + 1),
  };
}

export function formatUsage(progName) {
  return `usage: ${progName} [-h] --domain DOMAIN\n`;
}

export function formatHelp(progName) {
  return (
    `${formatUsage(progName)}\n` +
    "options:\n" +
    "  -h, --help       show this help message and exit\n" +
    "  --domain DOMAIN\n"
  );
}

export function parseArgs(argv) {
  let domain;
  let awaitingDomainValue = false;
  let stopParsingOptions = false;
  const unknown = [];

  for (const token of argv) {
    if (awaitingDomainValue) {
      if (!acceptsOptionalValue(token)) {
        throw new CLIUsageError("argument --domain: expected one argument");
      }

      domain = token;
      awaitingDomainValue = false;
      continue;
    }

    if (!stopParsingOptions) {
      if (token === "--") {
        stopParsingOptions = true;
        unknown.push(token);
        continue;
      }

      if (token.startsWith("-h")) {
        if (token.startsWith("-h=")) {
          throw new CLIUsageError(
            `argument -h/--help: ignored explicit argument '${token.slice(3)}'`,
          );
        }

        return { help: true };
      }

      if (token.startsWith("--")) {
        const { optionToken, explicitValue } = splitOptionToken(token);

        if (isLongOptionPrefix(optionToken, HELP_OPTION)) {
          if (explicitValue !== undefined) {
            throw new CLIUsageError(
              `argument -h/--help: ignored explicit argument '${explicitValue}'`,
            );
          }

          return { help: true };
        }

        if (isLongOptionPrefix(optionToken, DOMAIN_OPTION)) {
          if (explicitValue !== undefined) {
            domain = explicitValue;
          } else {
            awaitingDomainValue = true;
          }

          continue;
        }
      }
    }

    unknown.push(token);
  }

  if (awaitingDomainValue) {
    throw new CLIUsageError("argument --domain: expected one argument");
  }

  if (domain === undefined) {
    throw new CLIUsageError("the following arguments are required: --domain");
  }

  if (unknown.length > 0) {
    throw new CLIUsageError(`unrecognized arguments: ${unknown.join(" ")}`);
  }

  return { help: false, domain };
}

import { decodePunycode, encodePunycode } from "./bootstring.mjs";
import {
  formatCodePoint,
  formatLabel,
  IDNAError,
  InvalidCodepoint,
} from "./errors.mjs";

const LOWERCASE_LETTER_RE = /^\p{Ll}$/u;
const OTHER_LETTER_RE = /^\p{Lo}$/u;
const MODIFIER_LETTER_RE = /^\p{Lm}$/u;
const NONSPACING_MARK_RE = /^\p{Mn}$/u;
const SPACING_MARK_RE = /^\p{Mc}$/u;
const DECIMAL_NUMBER_RE = /^\p{Nd}$/u;
const MARK_RE = /^\p{M}$/u;

function isAsciiOnly(value) {
  return /^[\x00-\x7f]*$/.test(value);
}

function isValidAsciiLabelCharacter(codePoint) {
  return (
    (codePoint >= 0x41 && codePoint <= 0x5a) ||
    (codePoint >= 0x61 && codePoint <= 0x7a) ||
    (codePoint >= 0x30 && codePoint <= 0x39) ||
    codePoint === 0x2d
  );
}

function isValidUnicodeLabelCharacter(char) {
  return (
    LOWERCASE_LETTER_RE.test(char) ||
    OTHER_LETTER_RE.test(char) ||
    MODIFIER_LETTER_RE.test(char) ||
    NONSPACING_MARK_RE.test(char) ||
    SPACING_MARK_RE.test(char) ||
    DECIMAL_NUMBER_RE.test(char)
  );
}

function checkLabelLength(asciiLabel) {
  if (asciiLabel.length > 63) {
    throw new IDNAError("Label too long");
  }
}

function checkHyphenRestrictions(label) {
  const chars = Array.from(label);

  if (chars[0] === "-" || chars[chars.length - 1] === "-") {
    throw new IDNAError("Label must not start or end with a hyphen");
  }

  if (
    chars.length >= 4 &&
    chars[2] === "-" &&
    chars[3] === "-" &&
    chars.slice(0, 4).join("").toLowerCase() !== "xn--"
  ) {
    throw new IDNAError("Label has disallowed hyphens in 3rd and 4th position");
  }
}

function checkInitialCombiner(chars) {
  if (chars.length > 0 && MARK_RE.test(chars[0])) {
    throw new IDNAError("Label begins with an illegal combining character");
  }
}

function validateUnicodeLabel(label) {
  if (label.length === 0) {
    throw new IDNAError("Empty Label");
  }

  if (label.normalize("NFC") !== label) {
    throw new IDNAError("Label must be in Normalization Form C");
  }

  const chars = Array.from(label);
  checkHyphenRestrictions(label);
  checkInitialCombiner(chars);

  for (let index = 0; index < chars.length; index += 1) {
    const char = chars[index];
    const codePoint = char.codePointAt(0);

    if (codePoint < 0x80) {
      if (
        (codePoint >= 0x61 && codePoint <= 0x7a) ||
        (codePoint >= 0x30 && codePoint <= 0x39) ||
        codePoint === 0x2d
      ) {
        continue;
      }

      throw new InvalidCodepoint(codePoint, index + 1, label);
    }

    if (codePoint === 0x200c || codePoint === 0x200d) {
      throw new IDNAError(
        `Unknown codepoint adjacent to joiner ${formatCodePoint(codePoint)} at position ${index + 1} in ${formatLabel(label)}`,
      );
    }

    if (!isValidUnicodeLabelCharacter(char)) {
      throw new InvalidCodepoint(codePoint, index + 1, label);
    }
  }
}

function decodeALabel(label) {
  checkLabelLength(label);

  const payload = label.slice(4);

  if (payload.length === 0) {
    throw new IDNAError("Malformed A-label, no Punycode eligible content found");
  }

  if (label.endsWith("-")) {
    throw new IDNAError("A-label must not end with a hyphen");
  }

  let decoded;

  try {
    decoded = decodePunycode(payload);
  } catch {
    throw new IDNAError("Invalid A-label");
  }

  validateUnicodeLabel(decoded);

  if (`xn--${encodePunycode(decoded)}`.toLowerCase() !== label.toLowerCase()) {
    throw new IDNAError("Invalid A-label");
  }

  return decoded;
}

function validateAsciiLabel(label) {
  if (label.length === 0) {
    throw new IDNAError("Empty Label");
  }

  if (label.toLowerCase().startsWith("xn--")) {
    decodeALabel(label);
    return;
  }

  checkHyphenRestrictions(label);
  checkLabelLength(label);

  const chars = Array.from(label);

  for (let index = 0; index < chars.length; index += 1) {
    const codePoint = chars[index].codePointAt(0);

    if (!isValidAsciiLabelCharacter(codePoint)) {
      throw new InvalidCodepoint(codePoint, index + 1, label);
    }
  }
}

export function encodeLabel(label) {
  if (isAsciiOnly(label)) {
    validateAsciiLabel(label);
    return label;
  }

  validateUnicodeLabel(label);
  const encoded = `xn--${encodePunycode(label)}`;
  checkLabelLength(encoded);
  return encoded;
}

export function decodeLabel(label) {
  if (isAsciiOnly(label)) {
    if (label.toLowerCase().startsWith("xn--")) {
      return decodeALabel(label);
    }

    validateAsciiLabel(label);
    return label.toLowerCase();
  }

  validateUnicodeLabel(label);
  return label;
}

export function formatCodePoint(codePoint) {
  return `U+${codePoint.toString(16).toUpperCase().padStart(4, '0')}`;
}

export class IDNAError extends Error {
  constructor(message) {
    super(message);
    this.name = 'IDNAError';
  }
}

export class InvalidCodepoint extends IDNAError {
  constructor(codePoint, position, label) {
    super(`Codepoint ${formatCodePoint(codePoint)} at position ${position} of '${label}' not allowed`);
    this.name = 'InvalidCodepoint';
  }
}

export class InvalidCodepointContext extends IDNAError {
  constructor(codePoint, position, label) {
    super(`Codepoint ${formatCodePoint(codePoint)} not allowed at position ${position} in '${label}'`);
    this.name = 'InvalidCodepointContext';
  }
}

export class IDNABidiError extends IDNAError {
  constructor(message) {
    super(message);
    this.name = 'IDNABidiError';
  }
}
